SELECT id, country, city, signup_date, is_active, credit_limit, age, LAG(age) OVER w_grp AS prev_age, LEAD(age) OVER w_grp AS next_age, LEAD(credit_limit) OVER w_grp AS next_credit_limit, LAG(credit_limit) OVER w_grp AS prev_credit_limit, ROW_NUMBER() OVER w_grp AS row_seq, CORR(credit_limit, age) OVER (PARTITION BY country) AS corr_credit_limit_age FROM customers WINDOW w_grp AS (PARTITION BY city, segment ORDER BY signup_date, id);
